import 'fake-indexeddb/auto';

import { beforeEach, describe, expect, it } from 'vitest';

import {
  forget,
  getLastOpenedId,
  listRemembered,
  remember,
  setLastOpenedId,
} from '../../src/storage/registry';

/** Drop the registry database so each test starts empty. */
function reset(): Promise<void> {
  return new Promise((resolve) => {
    const request = indexedDB.deleteDatabase('upm-registry');
    request.onsuccess = () => resolve();
    request.onerror = () => resolve();
    request.onblocked = () => resolve();
  });
}

beforeEach(async () => {
  await reset();
});

describe('registry', () => {
  it('remembers a database and its last-opened id', async () => {
    await remember({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    await setLastOpenedId('db-1');

    const stored = await listRemembered();
    expect(stored).toHaveLength(1);
    expect(stored[0]).toMatchObject({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    expect(await getLastOpenedId()).toBe('db-1');
  });

  it('updates an existing label instead of duplicating it', async () => {
    await remember({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    await remember({ id: 'db-1', label: 'Work (renamed)', path: 'upm/work.db' });

    const stored = await listRemembered();
    expect(stored).toHaveLength(1);
    expect(stored[0]?.label).toBe('Work (renamed)');
  });

  it('ignores databases that have not been saved yet', async () => {
    await remember({ id: '', label: 'Draft', path: 'upm/draft.db' });
    expect(await listRemembered()).toHaveLength(0);
  });

  it('forgets a database and clears a matching last-opened id', async () => {
    await remember({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    await remember({ id: 'db-2', label: 'Home', path: 'upm/home.db' });
    await setLastOpenedId('db-1');

    await forget('db-1');

    expect((await listRemembered()).map((item) => item.id)).toEqual(['db-2']);
    expect(await getLastOpenedId()).toBeNull();

    await forget('db-2');
    expect(await listRemembered()).toHaveLength(0);
  });
});
